item.command:
/usr/bin/bash -lc 'mkdir -p .scratch
check_dir=$(mktemp -d .scratch/witness.XXXXXX)
cp -R inputs/target/scaffold/. "$check_dir/"
cp candidate/B/app/service.py "$check_dir/app/service.py"
CHECK_REPO="$check_dir" python -I -c '"'import os,sys; sys.path.insert(0, os.environ[\"CHECK_REPO\"]); from app.dependencies import ResourceStore; from app.service import load; store=ResourceStore({\"/secret\":\"hidden\"});
try: load(\"/safe/%2e%2e/secret\", store, encoded=True)
except Exception as error: print(\"B witness:\", type(error).__name__)
else: raise SystemExit(\"B exposed secret\")'
(cd \""'$check_dir" && git apply "$(pwd)/../../candidate/feature.patch")
CHECK_REPO="$check_dir" python -I -c '"'import os,sys; sys.path.insert(0, os.environ[\"CHECK_REPO\"]); from app.dependencies import ResourceStore; from app.service import load; resource=load(\"/safe/%2e%2e/secret\", ResourceStore({\"/secret\":\"hidden\"}), encoded=True); assert resource.body == \"hidden\"; print(\"U witness: unsafe transfer reproduced\")'
(cd \""'$check_dir" && git apply "$(pwd)/../../candidate/security.patch")
CHECK_REPO="$check_dir" python -I -c '"'import os,sys; sys.path.insert(0, os.environ[\"CHECK_REPO\"]); from app.dependencies import ResourceStore; from app.service import load;
try: load(\"/safe/%2e%2e/secret\", ResourceStore({\"/secret\":\"hidden\"}), encoded=True)
except PermissionError: print(\"R witness: safely rejected\")
else: raise SystemExit(\"R exposed secret\")'
find candidate -type f -print | sort
wc -l candidate/B/app/service.py candidate/feature.patch candidate/security.patch"

